head.script:
scwin.onpageload = function () {
    console.log("GitHub Manager 페이지 로드 시작");

    // 팝업에서 전달받은 프로젝트 데이터 처리
    scwin.initializeProjectData();

    // 초기값 설정
    dm_ui_state.set("isLoading", "false");
    dm_ui_state.set("loadingMessage", "");
    dm_ui_state.set("currentView", "repositories");
    dm_auth_status.set("needsLogin", "true");

    // 이벤트 핸들러 초기화
    scwin.initializeEventHandlers();

    // OAuth 성공 메시지 리스너 추가
    // scwin.initializeOAuthMessageListener();

    // 인증 상태 확인
    scwin.checkAuthenticationStatus();
};

// 프로젝트 데이터 초기화 함수
scwin.initializeProjectData = function() {
    try {
        // 팝업에서 전달받은 데이터 확인
        var popupData = $p.getParameter("project_param");
        console.log("팝업에서 전달받은 데이터:", popupData);

        if (popupData) {

            // 프로젝트 정보를 폼에 설정
            dm_github_form.set("projectId", popupData.projectId);

            console.log("프로젝트 정보 설정 완료:", {
                projectId: popupData.projectId,
                projectName: popupData.projectName,
                userId: popupData.userId
            });

            // 현재 프로젝트 정보를 전역 변수에 저장
            scwin.currentProjectData = popupData;

        } else {
            console.warn("팝업에서 전달받은 프로젝트 데이터가 없습니다. 기본값을 사용합니다.");
            dm_github_form.set("projectId", "default-project-id");
            scwin.currentProjectData = null;
        }
    } catch (e) {
        console.error("프로젝트 데이터 초기화 오류:", e);
        dm_github_form.set("projectId", "default-project-id");
        scwin.currentProjectData = null;
    }
};

// 이벤트 핸들러 초기화
scwin.initializeEventHandlers = function () {
    try {
        // 검색 키워드 입력 이벤트 핸들러 (실시간 검색)
        setTimeout(function () {
            var searchInput = document.querySelector('input[ref="data:dm_github_form.repoSearchKeyword"]');
            if (searchInput) {
                searchInput.addEventListener('input', function () {
                    var value = this.value;
                    setTimeout(function () {
                        scwin.filterRepositories(value);
                    }, 300); // 300ms 디바운스 적용
                });
                console.log("검색 입력 이벤트 핸들러 연결됨");
            }
        }, 100);

        console.log("이벤트 핸들러 초기화 완료");
    } catch (e) {
        console.error("이벤트 핸들러 초기화 실패:", e);
    }
};

// OAuth 성공 메시지 리스너 초기화
scwin.initializeOAuthMessageListener = function() {
    try {
        // postMessage 이벤트 리스너 추가 (iframe 방식 OAuth 대응)
        window.addEventListener('message', function(event) {
            console.log("부모 창에서 메시지 수신:", event);

            if (event.data && event.data.type === 'githubAuthSuccess') {
                console.log("GitHub OAuth 성공 메시지 수신:", event.data);

                // 성공 알림 표시
                if (typeof $c !== 'undefined' && $c.win && $c.win.alert) {
                    $c.win.alert("������ GitHub 연동이 성공적으로 완료되었습니다!\n\n사용자: @" + (event.data.data.username || ""));
                }

                // 인증 상태 다시 확인
                setTimeout(function() {
                    scwin.checkAuthenticationStatus();
                }, 1000);
            }
        });

        console.log("OAuth 메시지 리스너 초기화 완료");
    } catch (e) {
        console.error("OAuth 메시지 리스너 초기화 실패:", e);
    }
};

// GitHub 인증 상태 확인 (AJAX 방식 - myPage.xml 패턴 참조)
scwin.checkAuthenticationStatus = function () {
    console.log("GitHub 인증 상태 확인 중... (AJAX 방식)");
    scwin.setLoading(true, "인증 상태 확인 중...");

    try {    
        // myPage.xml과 동일한 AJAX 패턴 사용
        // 먼저 간단한 테스트 엔드포인트로 시도
        $.ajax({
            url: "/InsWebApp/github/auth/status.pwkjson",
            type: "GET",
            dataType: "json",
            success: function (result) {
                scwin.setLoading(false);
                console.log("인증 상태 확인 완료:", result);

                if (result && result.authenticated === true) {
                    // 인증된 상태
                    console.log("사용자 인증됨 - 인증된 UI 표시");
                    dm_auth_status.set("isAuthenticated", "true");
                    dm_auth_status.set("username", result.user ? result.user.login || "" : "");
                    dm_auth_status.set("avatarUrl", result.user ? result.user.avatar_url || "" : "");
                    dm_auth_status.set("hasGitHubApp", result.hasSelectedRepo ? "true" : "false");
                    dm_auth_status.set("needsLogin", "false");

                    scwin.showAuthenticatedUI();
                    scwin.loadConnectedRepositories();
                } else {
                    // 인증되지 않은 상태
                    console.log("사용자 인증되지 않음 - 로그인 필요 UI 표시");
                    scwin.showLoginRequiredUI();
                }
            },
            error: function (xhr, status, error) {
                scwin.setLoading(false);
                console.error("=== AJAX 요청 실패 상세 정보 ===");
                console.error("Status:", status);
                console.error("Error:", error);
                console.error("HTTP Status:", xhr.status);
                console.error("Response Text:", xhr.responseText);
                console.error("Request URL:", "/InsWebApp/github/test.pwkjson");
                console.error("XHR Object:", xhr);
                console.error("=== 실패 정보 끝 ===");
                scwin.showLoginRequiredUI();
            }
        });
    } catch (e) {
    scwin.setLoading(false);
        console.error("AJAX 호출 오류:", e);
        scwin.showLoginRequiredUI();    
    }
};

// 인증 상태 확인 완료 핸들러
scwin.checkAuthenticationStatus_submitdone = function(e) {
    scwin.setLoading(false);
    console.log("인증 상태 확인 완료:", e);
    console.log("responseJSON:", e.responseJSON);
    console.log("responseText:", e.responseText);

        var result = null;
        if (e.responseJSON) {
            result = e.responseJSON;
        } else if (e.responseText) {
            result = JSON.parse(e.responseText);
        }

        console.log("파싱된 결과:", result);
        console.log("authenticated 값:", result ? result.authenticated : "없음");

        if (result && result.authenticated === true) {
            // 인증된 상태
            console.log("사용자 인증됨 - 인증된 UI 표시");
            dm_auth_status.set("isAuthenticated", "true");
            dm_auth_status.set("username", result.user ? result.user.login || "" : "");
            dm_auth_status.set("avatarUrl", result.user ? result.user.avatar_url || "" : "");
            dm_auth_status.set("hasGitHubApp", result.hasSelectedRepo ? "true" : "false");
            dm_auth_status.set("needsLogin", "false");

            scwin.showAuthenticatedUI();
            scwin.loadConnectedRepositories();
        } else {
            // 인증되지 않은 상태
            console.log("사용자 인증되지 않음 - 로그인 필요 UI 표시");
            scwin.showLoginRequiredUI();
        }

};

// 인증 상태 확인 실패 핸들러
scwin.checkAuthenticationStatus_submiterror = function(e) {
    scwin.setLoading(false);
    console.error("인증 상태 확인 실패:", e);
    scwin.showLoginRequiredUI();
};

// GitHub 인증 상태 확인 완료 핸들러
scwin.checkAuthStatus_submit_done = function(e) {
    scwin.setLoading(false);
    console.log("인증 상태 확인 완료:", e);
    console.log("e.responseJSON:", e.responseJSON);
    console.log("e.responseText:", e.responseText);
    console.log("e:", e);

    var result = null;
    try {
        if (e.responseJSON) {
            result = e.responseJSON;
        } else if (e.responseText) {
            result = JSON.parse(e.responseText);
        }
    } catch (parseError) {
        console.error("JSON 파싱 오류:", parseError);
        result = null;
    }

    console.log("파싱된 결과:", result);
    console.log("authenticated 값:", result ? result.authenticated : "없음");

    if (result && result.authenticated === true) {
        // 인증된 상태
        console.log("사용자 인증됨 - 인증된 UI 표시");
        dm_auth_status.set("isAuthenticated", "true");
        dm_auth_status.set("username", result.user ? result.user.login || "" : "");
        dm_auth_status.set("avatarUrl", result.user ? result.user.avatar_url || "" : "");
        dm_auth_status.set("hasGitHubApp", result.hasSelectedRepo ? "true" : "false");
        dm_auth_status.set("needsLogin", "false");

        scwin.showAuthenticatedUI();
        scwin.loadConnectedRepositories();
    } else {
        // 인증되지 않은 상태
        console.log("사용자 인증되지 않음 - 로그인 필요 UI 표시");
        scwin.showLoginRequiredUI();
    }
};

// GitHub 인증 상태 확인 실패 핸들러
scwin.checkAuthStatus_submiterror = function(e) {
    scwin.setLoading(false);
    console.log("인증 상태 확인 실패 - 로그인 필요:", e);
    scwin.showLoginRequiredUI();
};

