/**
 * GitHub 로그인 팝업을 열고, 콜백 메시지를 비동기적으로 처리합니다.
 * SPA 환경에서 페이지 새로고침 없이 안전하게 인증을 완료하기 위한 표준 방식입니다.
 */
/**
 * GitHub 로그인을 WebSquare 표준 팝업으로 처리합니다.
 */
scwin.redirectToGitHubLogin = function() {
    console.log("GitHub 로그인 요청 시작 (WebSquare 표준 팝업 방식)");

    try {
        // OAuth URL 생성
        const baseUrl = window.location.protocol + "//" + window.location.host;
        let githubAuthStartUrl = baseUrl + "/InsWebApp/github/auth/start";

        // 현재 프로젝트 데이터에서 사용자 ID와 프로젝트 ID 가져오기
        const params = [];
        if (scwin.currentProjectData) {
            if (scwin.currentProjectData.projectId) {
                params.push("projectId=" + encodeURIComponent(scwin.currentProjectData.projectId));
                console.log("프로젝트 ID를 OAuth에 포함:", scwin.currentProjectData.projectId);
            }
            if (scwin.currentProjectData.userId) {
                params.push("userId=" + encodeURIComponent(scwin.currentProjectData.userId));
                console.log("사용자 ID를 OAuth에 포함:", scwin.currentProjectData.userId);
            }
        }

        // WebSquare에서 추가 사용자 정보 가져오기 시도
        if (!scwin.currentProjectData || !scwin.currentProjectData.userId) {
            try {
                // 다양한 방법으로 사용자 ID 가져오기 시도
                let userId = null;

                // WebSquare 파라미터에서 시도
                try {
                    userId = $p.getParameter("userId") || $p.getParameter("user_id");
                } catch(e) {}

                // 세션 스토리지에서 시도
                if (!userId && typeof sessionStorage !== 'undefined') {
                    userId = sessionStorage.getItem("userId") || sessionStorage.getItem("userEmail");
                }

                // 로컬 스토리지에서 시도
                if (!userId && typeof localStorage !== 'undefined') {
                    userId = localStorage.getItem("userId") || localStorage.getItem("userEmail");
                }

                if (userId && userId.trim() && userId !== "user01") {
                    params.push("userId=" + encodeURIComponent(userId));
                    console.log("추가로 찾은 사용자 ID를 OAuth에 포함:", userId);
                }
            } catch(e) {
                console.log("추가 사용자 ID 찾기 실패:", e);
            }
        }

        // URL 파라미터 추가
        if (params.length > 0) {
            githubAuthStartUrl += "?" + params.join("&");
        }

        console.log("OAuth 시작 URL:", githubAuthStartUrl);

        // 팝업에 전달할 데이터
        const popupData = {
            authUrl: githubAuthStartUrl,
            projectData: scwin.currentProjectData,
            callbackFn: function(result) {
                console.log("GitHub 인증 콜백 수신:", result);

                if (result && result.status === 'success') {
                    console.log("GitHub 인증 성공!");
                    $c.win.alert("GitHub 계정이 성공적으로 연동되었습니다.");

                    // 인증 성공 처리
                    dm_auth_status.set("isAuthenticated", "true");
                    dm_auth_status.set("needsLogin", "false");

                    if (result.data && result.data.user) {
                        dm_auth_status.set("username", result.data.user.login || "");
                        dm_auth_status.set("avatarUrl", result.data.user.avatar_url || "");
                    }
                    dm_auth_status.set("hasGitHubApp", result.data && result.data.hasSelectedRepo ? "true" : "false");

                    // UI 업데이트
                    scwin.showAuthenticatedUI();
                    scwin.loadConnectedRepositories();

                } else {
                    const errorMessage = result && result.data ? result.data.message : "알 수 없는 오류";
                    console.error("GitHub 인증 실패:", errorMessage);
                    $c.win.alert("GitHub 계정 연동에 실패했습니다: " + errorMessage);
                }
            }
        };

        // 전역 콜백 함수 등록
        window.githubAuthCallback = popupData.callbackFn;

        // postMessage 이벤트 리스너 등록
        const messageListener = function(event) {
            console.log("postMessage 수신:", event);

            // 보안을 위해 origin 확인
            if (event.origin !== window.location.origin) {
                console.warn("다른 origin에서 온 메시지 무시:", event.origin);
                return;
            }

            if (event.data && event.data.type === 'githubAuthResult') {
                console.log("GitHub 인증 결과 수신:", event.data.result);

                // 이벤트 리스너 제거
                window.removeEventListener('message', messageListener);

                // 콜백 함수 호출
                if (typeof popupData.callbackFn === 'function') {
                    popupData.callbackFn(event.data.result);
                }
            }
        };

        window.addEventListener('message', messageListener);

        console.log("브라우저 팝업으로 GitHub OAuth 시작:", githubAuthStartUrl);

        // WebSquare 팝업 대신 직접 브라우저 팝업 사용
        const authWindow = window.open(
            githubAuthStartUrl,
            'github_oauth_popup',
            'width=800,height=650,scrollbars=yes,resizable=yes,toolbar=no,menubar=no,location=no,status=no'
        );

        if (authWindow) {
            // 팝업이 닫힐 때까지 주기적으로 확인
            const checkClosed = setInterval(() => {
                if (authWindow.closed) {
                    clearInterval(checkClosed);
                    console.log("GitHub OAuth 팝업이 닫혔습니다");

                    // 이벤트 리스너 정리
                    window.removeEventListener('message', messageListener);

                    // 인증 상태 재확인 (postMessage 실패 시 백업)
                    setTimeout(() => {
                        scwin.checkAuthenticationStatus();
                    }, 1000);
                }
            }, 1000);

            // 5분 후 자동 정리
            setTimeout(() => {
                clearInterval(checkClosed);
                window.removeEventListener('message', messageListener);
                if (authWindow && !authWindow.closed) {
                    authWindow.close();
                }
            }, 300000);
        } else {
            console.error("팝업이 차단되었습니다. 팝업 차단 해제 후 다시 시도해주세요.");
            window.removeEventListener('message', messageListener);
            $c.win.alert("팝업이 차단되었습니다. 브라우저 설정에서 팝업 차단을 해제한 후 다시 시도해주세요.");
        }

    } catch (e) {
        console.error("GitHub 로그인 팝업 실행 오류:", e);
        $c.win.alert("GitHub 인증을 시작할 수 없습니다: " + e.message);
    }
};

// 테스트용 GitHub 컨트롤러 연결 테스트 (새로 추가)
scwin.testGitHubController = function () {
    console.log("GitHub 컨트롤러 테스트 시작");
    scwin.setLoading(true, "GitHub 컨트롤러 연결 테스트 중...");

    try {
        var baseUrl = window.location.protocol + "//" + window.location.host;
        var testUrl = baseUrl + "/InsWebApp/github/test";

        console.log("GitHub 컨트롤러 테스트 URL:", testUrl);

        fetch(testUrl, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json'
            }
        })
        .then(function(response) {
            scwin.setLoading(false);

            if (response.ok) {
                return response.json();
            } else {
                console.error("GitHub 컨트롤러 테스트 오류:", response.status, response.statusText);
                throw new Error("HTTP " + response.status);
            }
        })
        .then(function(result) {
            console.log("GitHub 컨트롤러 테스트 결과:", result);

            if (result && result.success) {
                $c.win.alert("GitHub 컨트롤러가 정상적으로 동작합니다!\n\n" +
                    "메시지: " + result.message + "\n" +
                    "시간: " + result.timestamp);
            } else {
                $c.win.alert("GitHub 컨트롤러 테스트 실패");
            }
        })
        .catch(function(error) {
            scwin.setLoading(false);
            console.error("GitHub 컨트롤러 테스트 실패:", error);
            $c.win.alert("GitHub 컨트롤러에 연결할 수 없습니다.\n\n오류: " + error.message);
        });
    } catch (e) {
        scwin.setLoading(false);
        console.error("컨트롤러 테스트 실행 오류:", e);
        $c.win.alert("컨트롤러 테스트 중 오류가 발생했습니다.");
    }
};

// 로그인 필요 UI 표시
scwin.showLoginRequiredUI = function () {
    dm_auth_status.set("needsLogin", "true");
    dm_auth_status.set("isAuthenticated", "false");

    try {
        // 메인 컨텐츠 숨기기
        var mainContent = $p.getComponentById("github_main_content");
        if (mainContent) {
            mainContent.hide();
        }

        // 로그인 필요 섹션 표시
        var loginSection = $p.getComponentById("login_required_section");
        if (loginSection) {
            loginSection.show();
            loginSection.removeClass("hidden");
        } else {
            // 로그인 필요 섹션이 없으면 동적으로 생성
            scwin.createLoginRequiredSection();
        }
    } catch (e) {
