};

// 연결된 레포지토리 목록 로드 (수정됨)
scwin.loadConnectedRepositories = function () {
    if (dm_auth_status.get("needsLogin") === "true") {
        console.log("인증되지 않은 상태 - 레포지토리 로드 건너뜀");
        return;
    }

    var projectId = dm_github_form.get("projectId");
    scwin.setLoading(true, "연결된 레포지토리 목록 로딩 중...");

    var requestData = {
        projectId: projectId
    };

    try {
        $c.sbm.execute(sbm_loadRepositories, requestData).then(function (e) {
            scwin.setLoading(false);
            console.log("연결된 레포지토리 목록 로드 완료:", e);

            scwin.updateRepositoryDisplay();

            // 첫 번째 레포지토리 자동 선택
            if (dlt_GitHubRepositoryVoList.getTotalRow() > 0) {
                dlt_GitHubRepositoryVoList.setFocusedRow(0);
                scwin.onRepositorySelect();
            } else {
                scwin.showEmptyRepositoryState();
            }
        }).catch(function (e) {
            scwin.setLoading(false);
            console.error("레포지토리 목록 로드 실패:", e);

            var errorMsg = scwin.getErrorMessage(e);
            $c.win.alert("연결된 레포지토리 목록을 불러올 수 없습니다.\n" + errorMsg);

            if (e.status === 401) {
                scwin.showLoginRequiredUI();
            }
        });
    } catch (e) {
        scwin.setLoading(false);
        console.error("submission 실행 오류:", e);
        scwin.showEmptyRepositoryState();
    }
};

// 레포지토리 표시 업데이트
scwin.updateRepositoryDisplay = function () {
    try {
        var totalRepos = dlt_GitHubRepositoryVoList.getTotalRow();
        var privateRepos = 0;
        var publicRepos = 0;

        for (var i = 0; i < totalRepos; i++) {
            if (dlt_GitHubRepositoryVoList.getCellData(i, "isPrivate") === "true") {
                privateRepos++;
            } else {
                publicRepos++;
            }
        }

        var countText = "총 " + totalRepos + "개 레포지토리 (" + 
            publicRepos + "개 공개, " + privateRepos + "개 비공개)";

        var countElement = document.getElementById("repo-count-info");
        if (countElement) {
            countElement.textContent = countText;
        }

        console.log("레포지토리 표시 업데이트:", countText);
    } catch (e) {
        console.error("레포지토리 표시 업데이트 실패:", e);
    }
};

