// 로딩 표시 업데이트
scwin.updateLoadingDisplay = function (isLoading) {
    try {
        var loadingElement = document.getElementById("loading-overlay");
        if (loadingElement) {
            loadingElement.style.display = isLoading ? "flex" : "none";

            if (isLoading) {
                var messageElement = loadingElement.querySelector(".loading-message");
                if (messageElement) {
                    messageElement.textContent = dm_ui_state.get("loadingMessage") || "처리 중...";
                }
            }
        }
