// GitHub 연결 테스트 (서브미션 방식)
scwin.testGitHubConnection = function() {
    console.log("GitHub 연결 테스트 시작 (서브미션 방식)");

    try {
        // 웹스퀘어 서브미션 실행
        $c.sbm.execute(sbm_testGitHubConnection);
    } catch (e) {
        console.error("서브미션 실행 오류:", e);
        $c.win.alert("❌ 서브미션 실행 중 오류 발생\n\n" + e.message);
    }
};

// GitHub 연결 테스트 완료 핸들러
scwin.testGitHubConnection_submitdone = function(e) {
    console.log("GitHub 연결 테스트 완료:", e);
    console.log("responseJSON:", e.responseJSON);
    console.log("responseText:", e.responseText);

    try {
        var result = null;
        if (e.responseJSON) {
            result = e.responseJSON;
        } else if (e.responseText) {
            result = JSON.parse(e.responseText);
        }

        if (result && result.success) {
            $c.win.alert("✅ GitHub 컨트롤러 연결 성공!\n\n메시지: " + result.message + "\n타임스탬프: " + result.timestamp);
        } else {
            $c.win.alert("❌ GitHub 컨트롤러 테스트 실패\n\n" + JSON.stringify(result));
        }
    } catch (parseError) {
        console.error("응답 파싱 오류:", parseError);
        $c.win.alert("❌ 응답 파싱 실패\n\n원본 응답: " + e.responseText);
    }
};

// GitHub 연결 테스트 실패 핸들러
scwin.testGitHubConnection_submiterror = function(e) {
    console.error("GitHub 연결 테스트 실패:", e);
    $c.win.alert("❌ GitHub 컨트롤러 연결 실패\n\n오류: " + (e.errorMsg || e.message || "알 수 없는 오류"));
};

// 테스트용 GitHub 인증 시작 (새 창)
scwin.testGitHubAuthStart = function() {
    console.log("테스트용 GitHub 인증 시작 (새 창)");

    try {
        var baseUrl = window.location.protocol + "//" + window.location.host;
        var authUrl = baseUrl + "/InsWebApp/github/auth/start";

        // 현재 프로젝트 정보가 있으면 OAuth 요청에 포함
        var params = [];
        if (scwin.currentProjectData && scwin.currentProjectData.projectId) {
            params.push("projectId=" + encodeURIComponent(scwin.currentProjectData.projectId));
            console.log("프로젝트 ID를 OAuth에 포함:", scwin.currentProjectData.projectId);
        }
        if (scwin.currentProjectData && scwin.currentProjectData.userId) {
            params.push("userId=" + encodeURIComponent(scwin.currentProjectData.userId));
            console.log("사용자 ID를 OAuth에 포함:", scwin.currentProjectData.userId);
        }

        // 추가 사용자 ID 찾기 (프로젝트 데이터에 없는 경우)
        if (!scwin.currentProjectData || !scwin.currentProjectData.userId) {
            try {
                var userId = null;

                // WebSquare 파라미터에서 시도
                try {
                    userId = $p.getParameter("userId") || $p.getParameter("user_id");
                } catch(e) {}

                // 세션 스토리지에서 시도
                if (!userId && typeof sessionStorage !== 'undefined') {
                    userId = sessionStorage.getItem("userId") || sessionStorage.getItem("userEmail");
                }

                // 로컬 스토리지에서 시도
                if (!userId && typeof localStorage !== 'undefined') {
                    userId = localStorage.getItem("userId") || localStorage.getItem("userEmail");
                }

                if (userId && userId.trim() && userId !== "user01") {
                    params.push("userId=" + encodeURIComponent(userId));
                    console.log("WebSquare에서 추가로 찾은 사용자 ID를 OAuth에 포함:", userId);
                }
            } catch(e) {
                console.log("WebSquare 추가 사용자 ID 찾기 실패:", e);
            }
        }

        if (params.length > 0) {
            authUrl += "?" + params.join("&");
        }

        console.log("인증 URL:", authUrl);

        // 콜백 함수 정의
        var callbackFn = function(result) {
            console.log("GitHub 인증 테스트 콜백 수신:", result);

            if (result && result.status === 'success') {
                console.log("GitHub 인증 성공!");
                $c.win.alert("GitHub 계정이 성공적으로 연동되었습니다.");

                // 인증 상태 재확인
                setTimeout(function() {
                    scwin.checkAuthenticationStatus();
                }, 1000);
            } else {
                var errorMessage = result && result.data ? result.data.message : "알 수 없는 오류";
                console.error("GitHub 인증 실패:", errorMessage);
                $c.win.alert("GitHub 계정 연동에 실패했습니다: " + errorMessage);
            }
        };

        // 전역 콜백 함수 등록
        window.githubAuthCallback = callbackFn;

        console.log("브라우저 팝업으로 GitHub OAuth 시작:", authUrl);

        // WebSquare 팝업 대신 직접 브라우저 팝업 사용
        var authWindow = window.open(
            authUrl,
            'github_oauth_popup',
            'width=800,height=650,scrollbars=yes,resizable=yes,toolbar=no,menubar=no,location=no,status=no'
        );

        if (authWindow) {
            // 팝업이 닫힐 때까지 주기적으로 확인
            var checkClosed = setInterval(function() {
                if (authWindow.closed) {
                    clearInterval(checkClosed);
                    console.log("GitHub OAuth 팝업이 닫혔습니다 - 인증 상태 재확인");
                    setTimeout(function() {
                        scwin.checkAuthenticationStatus();
                    }, 1000);
                }
            }, 1000);

            // 5분 후 자동 정리
            setTimeout(function() {
                clearInterval(checkClosed);
                if (authWindow && !authWindow.closed) {
                    authWindow.close();
                }
            }, 300000);
        } else {
            console.error("팝업이 차단되었습니다. 팝업 차단 해제 후 다시 시도해주세요.");
            $c.win.alert("팝업이 차단되었습니다. 브라우저 설정에서 팝업 차단을 해제한 후 다시 시도해주세요.");
        }

    } catch (e) {
        console.error("인증 시작 오류:", e);
        $c.win.alert("❌ 인증 시작 중 오류 발생\n\n" + e.message);
    }
};

// OAuth 팝업 닫기 액션
scwin.oauthPopup_closeAction = function() {
    console.log("OAuth 팝업이 닫혔습니다 - 인증 상태 재확인");
    setTimeout(function() {
        scwin.checkAuthenticationStatus();
    }, 1000);
};

