    }
};

// 백엔드 GitHub 인증 시작 완료 핸들러
scwin.testGitHubAuthRequest_submitdone = function(e) {
    console.log("백엔드 GitHub 인증 시작 완료:", e);
    console.log("responseJSON:", e.responseJSON);
    console.log("responseText:", e.responseText);

    try {
        // 응답이 리다이렉트인지 확인
        if (e.responseText && e.responseText.includes("github.com")) {
            console.log("GitHub 리다이렉트 감지");
            $c.win.alert("✅ 백엔드 인증 요청 성공!\n\n컨트롤러에서 GitHub으로 리다이렉트 처리됨");
        } else {
            var result = null;
            if (e.responseJSON) {
                result = e.responseJSON;
            } else if (e.responseText) {
                result = JSON.parse(e.responseText);
            }

            if (result && result.success) {
                $c.win.alert("✅ 백엔드 응답 수신:\n\n" + result.message);
            } else {
                $c.win.alert("✅ 백엔드 응답 수신:\n\n" + e.responseText.substring(0, 200) + "...");
            }
        }
    } catch (parseError) {
        console.error("응답 파싱 오류:", parseError);
        $c.win.alert("✅ 백엔드 응답 수신:\n\n" + e.responseText.substring(0, 200) + "...");
    }
};

// 백엔드 GitHub 인증 시작 실패 핸들러
scwin.testGitHubAuthRequest_submiterror = function(e) {
    console.error("백엔드 GitHub 인증 시작 실패:", e);
    $c.win.alert("❌ 백엔드 인증 요청 실패\n\n오류: " + (e.errorMsg || e.message || "알 수 없는 오류"));
};

